-- GeoFolio: lược đồ PostgreSQL tương ứng dữ liệu localStorage (khi chuyển sang backend)
create table users(id uuid primary key default gen_random_uuid(), name text not null, email text unique not null, password_hash text not null, role text not null check (role in ('teacher','student')), created_at timestamptz default now());
create table classes(id uuid primary key default gen_random_uuid(), teacher_id uuid references users(id) on delete cascade, name text not null, code text unique not null, created_at timestamptz default now());
create table class_members(class_id uuid references classes(id) on delete cascade, student_id uuid references users(id) on delete cascade, joined_at timestamptz default now(), primary key(class_id, student_id));
create table portfolio_items(id uuid primary key default gen_random_uuid(), student_id uuid references users(id) on delete cascade, title text not null, type text, description text, created_at timestamptz default now());
create table field_stops(id uuid primary key default gen_random_uuid(), student_id uuid references users(id) on delete cascade, title text not null, category text, lat double precision, lng double precision, note text, created_at timestamptz default now());
create table projects(id uuid primary key default gen_random_uuid(), student_id uuid references users(id) on delete cascade, title text not null, description text, due date, progress int default 0 check (progress between 0 and 100));
create table tasks(id uuid primary key default gen_random_uuid(), class_id uuid references classes(id) on delete cascade, type text, title text not null, due date);
create table submissions(id uuid primary key default gen_random_uuid(), task_id uuid references tasks(id) on delete cascade, student_id uuid references users(id) on delete cascade, note text, rubric int[4] check (rubric is null or array_length(rubric,1)=4), score numeric(3,1), feedback text, graded_by uuid references users(id), graded_at timestamptz, created_at timestamptz default now(), unique(task_id, student_id));
create table community_items(id uuid primary key default gen_random_uuid(), owner_id text not null, author text, title text not null, place text, description text, created_at timestamptz default now());
